using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new Exception("Edit required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var hook = s.gate.transform.Find("M_hook_dust");
            var src = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/InvestigationV36/R103/MECHANISM.fbx").GetComponentsInChildren<MeshFilter>().Single(f => f.name == "Hook_M");
            var before = hook.GetComponent<BoxCollider>().bounds;
            hook.GetComponent<MeshFilter>().sharedMesh = src.sharedMesh;
            var box = hook.GetComponent<BoxCollider>();
            box.center = src.sharedMesh.bounds.center;
            box.size = src.sharedMesh.bounds.size + Vector3.one * .006f;
            EditorSceneManager.MarkSceneDirty(s.gameObject.scene);
            EditorSceneManager.SaveScene(s.gameObject.scene);
            File.WriteAllText("Test/KetQua/investigation_r103/hook-collider.txt", "Before=" + before + "\nAfter=" + box.bounds + "\nShared mesh=" + src.sharedMesh.name);
            r.Log("Hook collider synchronized to new source bounds; obstruction rule retained");
        }
    }
}

